const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let state=null;
const money=v=>v===null?'Sob consulta':new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(v/100);
async function api(url,method='GET',data){const r=await fetch(url,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let v;try{v=await r.json()}catch{throw Error('O servidor de gestão não está disponível nesta prévia. Use a instalação Node.js.')}if(!r.ok){if(r.status===401)showLogin();throw Error(v.error||'Não foi possível concluir.')}return v}
function showLogin(){$('#login').hidden=false;$('#dashboard').hidden=true;$('#logout').hidden=true;state=null}
async function load(){state=await api('/api/admin/dashboard');$('#login').hidden=true;$('#dashboard').hidden=false;$('#logout').hidden=false;render();fillSettings()}
function render(){const products=state.products;$('#stat-products').textContent=products.filter(p=>p.published&&!p.archived).length;$('#stat-offers').textContent=products.filter(p=>p.offerActive&&p.published&&!p.archived).length;$('#stat-requests').textContent=state.requests.filter(r=>['novo','em_contacto'].includes(r.status)).length;$('#mode-badge').textContent=state.settings.demo?'Modo demonstração':'Loja ativa';const query=$('#admin-search').value.toLocaleLowerCase('pt'),archive=$('#show-archive').checked;$('#product-rows').innerHTML=products.filter(p=>(archive||!p.archived)&&`${p.name} ${p.category}`.toLocaleLowerCase('pt').includes(query)).map(p=>`<tr><td><b>${esc(p.name)}</b><small>${p.illustrative?'Demonstração':''}</small></td><td>${esc(p.category)}</td><td>${money(p.offerActive?p.offerPriceCents:p.priceCents)}${p.offerActive?'<small>Promoção ativa</small>':''}</td><td>${p.archived?'Arquivado':p.published?'Publicado':'Rascunho'}</td><td><button data-edit="${esc(p.id)}">Editar</button>${p.archived?`<button data-restore="${esc(p.id)}">Recuperar</button>`:`<button class="archive" data-archive="${esc(p.id)}">Arquivar</button>`}</td></tr>`).join('')||'<tr><td colspan="5">Sem produtos para estes filtros.</td></tr>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editProduct(products.find(p=>p.id===b.dataset.edit)));for(const action of ['archive','restore'])document.querySelectorAll(`[data-${action}]`).forEach(b=>b.onclick=async()=>{try{await api('/api/admin/products/'+b.dataset[action]+(action==='restore'?'/restore':''),action==='restore'?'POST':'DELETE',{});await load();$('#global-status').textContent=action==='restore'?'Produto recuperado.':'Produto arquivado. Pode recuperá-lo em Mostrar arquivo.'}catch(e){$('#global-status').textContent=e.message}});renderRequests();$('#audit-rows').innerHTML=state.audit.map(r=>`<tr><td>${esc(new Date(r.created).toLocaleString('pt-PT'))}</td><td>${esc(r.action)}</td><td>${esc(r.entity)}</td></tr>`).join('')||'<tr><td colspan="3">Ainda sem alterações.</td></tr>'}
function fillSettings(){const f=$('#settings-form');for(const[k,v]of Object.entries(state.settings)){const el=f.elements.namedItem(k);if(!el)continue;if(el.type==='checkbox')el.checked=!!v;else el.value=v??''}}
function editProduct(p={}){const f=$('#product-form');f.reset();f.elements.id.value=p.id||'';$('#editor-title').textContent=p.id?'Editar produto':'Novo produto';for(const k of ['name','category','description','unit','image','art','offerStart','offerEnd'])f.elements[k].value=p[k]??(k==='art'?'mercearia':'');f.elements.price.value=p.priceCents===null||p.priceCents===undefined?'':(p.priceCents/100).toFixed(2);f.elements.offerPrice.value=p.offerPriceCents===null||p.offerPriceCents===undefined?'':(p.offerPriceCents/100).toFixed(2);f.elements.published.checked=p.published!==false;f.elements.illustrative.checked=!!p.illustrative;$('#product-status').textContent='';$('#product-dialog').showModal()}
$('#new-product').onclick=()=>editProduct();$('#close-editor').onclick=()=>$('#product-dialog').close();$('#product-dialog').onclick=e=>{if(e.target===$('#product-dialog'))e.target.close()};$('#admin-search').oninput=render;$('#show-archive').onchange=render;
$('#login-form').onsubmit=async e=>{e.preventDefault();const f=e.target,button=f.querySelector('button');button.disabled=true;$('#login-status').textContent='A entrar…';try{await api('/api/login','POST',Object.fromEntries(new FormData(f)));f.reset();await load();$('#login-status').textContent=''}catch(err){$('#login-status').textContent=err.message}finally{button.disabled=false}};
$('#logout').onclick=async()=>{try{await api('/api/logout','POST',{});showLogin()}catch(e){$('#global-status').textContent=e.message}};
$('#product-form').onsubmit=async e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f)),id=v.id;const cents=x=>x===''?null:Math.round(Number(x)*100);Object.assign(v,{priceCents:cents(v.price),offerPriceCents:cents(v.offerPrice),published:f.elements.published.checked,illustrative:f.elements.illustrative.checked});const b=f.querySelector('button');b.disabled=true;try{await api('/api/admin/products'+(id?'/'+id:''),id?'PUT':'POST',v);$('#product-dialog').close();await load();$('#global-status').textContent='Produto guardado. O catálogo público já está atualizado.'}catch(err){$('#product-status').textContent=err.message}finally{b.disabled=false}};
$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f));v.demo=f.elements.demo.checked;v.ordersEnabled=f.elements.ordersEnabled.checked;const b=f.querySelector('button');b.disabled=true;try{await api('/api/admin/settings','PUT',v);await load();$('#settings-status').textContent='Dados da loja guardados.'}catch(err){$('#settings-status').textContent=err.message}finally{b.disabled=false}};
function renderRequests(){const labels={novo:'Novo',em_contacto:'Em contacto',confirmado:'Confirmado',concluido:'Concluído',cancelado:'Cancelado'};$('#request-cards').innerHTML=state.requests.map(r=>`<article class="request-card"><span class="eyebrow">${esc(r.reference)} · ${esc(new Date(r.created).toLocaleString('pt-PT'))}</span><h3>${esc(r.data.name)}</h3><a href="tel:${esc(r.data.phone.replace(/[^+\d]/g,''))}">${esc(r.data.phone)}</a><ul>${r.data.items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul><p>${esc(r.data.notes)}</p><label>Estado<select data-request="${esc(r.id)}">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${r.status===k?'selected':''}>${v}</option>`).join('')}</select></label><p class="request-status" role="status"></p></article>`).join('')||'<p>Nenhum pedido recebido. A receção só fica disponível depois de ativada nos dados da loja.</p>';document.querySelectorAll('[data-request]').forEach(b=>b.onchange=async()=>{const prev=state.requests.find(r=>r.id===b.dataset.request).status;b.disabled=true;try{await api('/api/admin/requests/'+b.dataset.request,'PUT',{status:b.value});await load()}catch(e){b.value=prev;b.closest('article').querySelector('.request-status').textContent=e.message}finally{b.disabled=false}})}
$('#refresh-requests').onclick=()=>load().catch(e=>$('#global-status').textContent=e.message);document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.admin-panel').forEach(s=>s.hidden=s.id!==b.dataset.panel);document.querySelectorAll('[data-panel]').forEach(x=>x.classList.toggle('active',x===b));$('#global-status').textContent=''});load().catch(e=>{showLogin();if(!e.message.includes('Entre na área'))$('#login-status').textContent=e.message});
$('#image-upload').onchange=async e=>{const file=e.target.files[0],status=$('#upload-status');if(!file)return;if(file.size>4*1024*1024){status.textContent='A imagem deve ter até 4 MB.';return}const submit=$('#product-form').querySelector('button');submit.disabled=true;status.textContent='A enviar imagem…';try{const r=await fetch('/api/admin/uploads',{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream'},body:file});const v=await r.json();if(!r.ok)throw Error(v.error);$('#product-form').elements.image.value=v.url;status.textContent='Imagem enviada. Guarde o produto para a publicar.'}catch(err){status.textContent=err.message||'Não foi possível enviar a imagem.'}finally{submit.disabled=false;e.target.value=''}};
